import random

def solve_optimal(grid):
    rows, cols = len(grid), len(grid[0])
    seen = [[False] * cols for _ in range(rows)]
    islands = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not seen[r][c]:
                islands += 1
                stack = [(r, c)]
                seen[r][c] = True
                while stack:
                    y, x = stack.pop()
                    for ny, nx in ((y + 1, x), (y - 1, x), (y, x + 1), (y, x - 1)):
                        if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] == 1 and not seen[ny][nx]:
                            seen[ny][nx] = True
                            stack.append((ny, nx))
    return islands

def solve_brute(grid):
    rows, cols = len(grid), len(grid[0])
    parent = {}
    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                parent[(r, c)] = (r, c)
    for (r, c) in list(parent):
        for nb in ((r + 1, c), (r, c + 1)):
            if nb in parent:
                parent[find(nb)] = find((r, c))
    return len({find(cell) for cell in parent})

def gen(rng, size):
    rows = rng.randint(1, {"tiny": 3, "small": 5, "large": 8}[size])
    cols = rng.randint(1, {"tiny": 3, "small": 5, "large": 8}[size])
    return [[[rng.randint(0, 1) for _ in range(cols)] for _ in range(rows)]]

def validate(args):
    grid = args[0]
    return 1 <= len(grid) <= 50 and len({len(r) for r in grid}) == 1 and 1 <= len(grid[0]) <= 50 and all(v in (0, 1) for r in grid for v in r)
